h(other=>{if(other!==box)other.classList.remove('is-open')});box.classList.toggle('is-open');if(box.classList.contains('is-open')){search.value='';options.forEach(option=>option.hidden=false);search.focus()}});search.addEventListener('input',()=>{const query=search.value.trim().toLowerCase();options.forEach(option=>option.hidden=query && !option.textContent.trim().toLowerCase().includes(query))});options.forEach(option=>option.addEventListener('click',()=>{target.value=option.dataset.value;toggle.querySelector('span').textContent=option.textContent.trim();options.forEach(item=>item.classList.toggle('is-selected',item===option));box.classList.remove('is-open')}))});document.addEventListener('click',()=>document.querySelectorAll('.report-filter-combobox.is-open').forEach(box=>box.classList.remove('is-open')));</script>
