@if($type==='student-list')<script>(()=>{const select=document.querySelector('select[name="print_grade_classes[]"]');if(!select)return;const picker=document.createElement('div');picker.className='report-class-picker';const toggle=document.createElement('button');toggle.type='button';toggle.className='report-class-picker-toggle';toggle.innerHTML='<span></span><i class="ti ti-chevron-down"></i>';const menu=document.createElement('div');menu.className='report-class-picker-menu';const search=document.createElement('input');search.type='search';search.className='form-control';search.placeholder='Search Class';const options=document.createElement('div');options.className='report-class-picker-options';const label=toggle.querySelector('span');const sync=()=>{const selected=[...select.options].filter(option=>option.selected).map(option=>option.textContent.trim());label.textContent=selected.join(', ');};[...select.options].forEach(option=>{const row=document.createElement('label');row.className='report-class-picker-option';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.value=option.value;checkbox.checked=option.selected;checkbox.addEventListener('change',()=>{option.selected=checkbox.checked;select.dispatchEvent(new Event('change',{bubbles:true}));sync()});row.append(checkbox,document.createTextNode(option.textContent.trim()));options.append(row)});menu.append(search,options);picker.append(toggle,menu);select.classList.add('d-none');select.parentElement.insertBefore(picker,select);toggle.addEventListener('click',event=>{event.stopPropagation();document.querySelectorAll('.report-class-picker.is-open').forEach(other=>{if(other!==picker)other.classList.remove('is-open')});picker.classList.toggle('is-open');if(picker.classList.contains('is-open'))search.focus()});search.addEventListener('input',()=>{const query=search.value.toLowerCase().trim();options.querySelectorAll('.report-class-picker-option').forEach(row=>row.hidden=query&&!row.textContent.toLowerCase().includes(query))});document.addEventListener('click',()=>picker.classList.remove('is-open'));sync()})();</script>@endif
@if($type==='student-list')<script>(()=>{const scope=document.querySelector('select[name="print_scope"]'),select=document.querySelector('select[name="print_grade_classes[]"]');if(!scope||!select)return;const field=select.closest('[class*="col-"]');const update=()=>{const show=scope.value==='selected_classes';field.hidden=!show;if(!show){[...select.options].forEach(option=>{option.selected=false});select.dispatchEvent(new Event('change',{bubbles:true}))}};scope.addEventListener('change',update);update()})();</script>@endif
